// ANA-02 — texto da cadencia de follow-up, deterministico.
// A Ana se apresenta como assistente: quem confirma horario e a equipe.
// Linguagem de clinica de diagnostico (exame, pedido medico) e CFM 2.336/2023.
// Cadencia: 1=D+1, 2=D+3, 3=D+7, 4=D+14, 5=D+30. Depois do 5 encerra.
const lead  = $('Um Lead por Vez').first().json;
const phone = lead.phone;
const step  = Number(lead.followup_step) || 1;

function primeiroNome(n) {
  const p = String(n || '').trim().split(/\s+/)[0] || '';
  if (p.length < 2 || !/^[A-Za-zÀ-ÿ]+$/.test(p)) return '';
  return p.charAt(0).toUpperCase() + p.slice(1).toLowerCase();
}
const nome = primeiroNome(lead.nome);

const lista = String(lead.exames_txt || '').split('; ').map(s => s.trim()).filter(Boolean);
const exame = lista.length === 1 ? lista[0]
            : lista.length === 2 ? (lista[0] + ' e ' + lista[1])
            : '';

const oi      = nome ? ('Oi, ' + nome) : 'Oi';
const orcDo   = exame ? ('o orçamento de *' + exame + '*') : 'o orçamento que te passei';
const oExame  = exame ? ('*' + exame + '*') : 'o exame';
const sobreEx = exame ? ('sobre *' + exame + '*') : 'sobre o seu exame';
const coleta  = lead.tem_lab === true
  ? '\n- Para exames de laboratório, também fazemos *coleta domiciliar*' : '';

const textos = {
  1: oi + ', tudo bem?' + ' Aqui é a Ana, assistente da Total Quality 😊\n\n'
   + 'Passando só pra saber se ficou alguma dúvida sobre ' + orcDo + '.\n'
   + 'Se quiser, me diz o melhor dia e período (manhã ou tarde) que eu deixo encaminhado pra nossa equipe confirmar o horário com você.',

  2: oi + '! Lembrei de você por aqui 💙\n\n'
   + 'Só pra facilitar:\n'
   + '- Atendemos de segunda a sexta, das 7h30 às 18h, na Av. Anchieta, 1010 – Centro de Caraguá\n'
   + '- Pagamento no PIX ou cartão'
   + coleta + '\n\n'
   + 'Quer que eu veja um horário pra você?',

  3: oi + '. Sei que a rotina nem sempre deixa espaço pra resolver essas coisas, e tá tudo bem 🙂\n\n'
   + 'Se alguma coisa te fez segurar o agendamento (valor, horário, preparo do exame), me conta que eu vejo como te ajudar.\n\n'
   + 'Se preferir que eu não mande mais lembretes, é só responder *parar*.',

  4: oi + '! Um lembrete rapidinho 😊\n\n'
   + 'Pedido médico costuma ter prazo de validade, principalmente quando o exame é pelo convênio. '
   + 'Se você ainda pretende fazer ' + oExame + ', vale não deixar passar.\n\n'
   + 'Me diz o melhor dia pra você que eu encaminho.',

  5: oi + '. Não quero ficar te incomodando, então essa é minha última mensagem ' + sobreEx + ' 🙂\n\n'
   + 'Me ajuda com uma resposta rapidinha?\n'
   + '*1* — Ainda quero agendar\n'
   + '*2* — Já resolvi / pode encerrar\n\n'
   + 'Se não der pra responder agora, sem problema: quando precisar, é só mandar um oi aqui ou ligar no (12) 3887-3535. '
   + 'Um abraço da equipe Total Quality 💙',
};

const mensagem = textos[step];
if (!mensagem) return [{ json: { skip: true, phone } }];

const gaps = { 1: 2, 2: 4, 3: 7, 4: 16, 5: null };
const due = gaps[step] ? new Date(Date.now() + gaps[step] * 86400000).toISOString() : null;

return [{ json: {
  phone, mensagem, step,
  pg_msg: JSON.stringify({ phone, conteudo: mensagem,
    dados: { evento: 'follow_up', passo: step, origem: 'ANA-02', modelo: 'texto fixo' } }),
  pg_lead: JSON.stringify({ phone, step, followup_due: due,
    proxima_acao: step === 5 ? 'encerrar' : 'aguardar_resposta' }),
} }];
